function isPrime(num) {
  if (num <= 1) return false;
  if (num <= 3) return true;
  if (num % 2 === 0 || num % 3 === 0) return false;

  for (let i = 5; i * i <= num; i += 6) {
    if (num % i === 0 || num % (i + 2) === 0) return false;
  }
  return true;
}

function processNumbers(numbers) {
  const results = [];
  for (let i = 0; i < numbers.length; i += 1) {
    if (numbers[i] > 1) { 
      let isNumPrime = true;
      if (numbers[i] <= 3) {
        isNumPrime = true;
      } else if (numbers[i] % 2 === 0 || numbers[i] % 3 === 0) {
        isNumPrime = false;
      } else {
        for (let j = 5; j * j <= numbers[i]; j += 6) {
          if (numbers[i] % j === 0 || numbers[i] % (j + 2) === 0) {
            isNumPrime = false;
            break;
          }
        }
      }
      results.push({ number: numbers[i], isPrime: isNumPrime });
    } else {
      results.push({ number: numbers[i], isPrime: false });
    }
  }
  return results;
}

