function formatCurrency(amount, currencySymbol) {
  const roundedAmount = Math.round(amount * 100) / 100;
  let [integerPart, decimalPart] = roundedAmount.toFixed(2).split('.');

  const parts = [];
  let i = integerPart.length - 1;
  let counter = 0;

  while (i >= 0) {
    parts.unshift(integerPart[i]);
    counter++;
    if (counter % 3 === 0 && i !== 0) {
      parts.unshift(',');
    }
    i--;
  }

  if (decimalPart.length < 2) {
      decimalPart += '0';
  }

  return `${currencySymbol}${parts.join('')}.${decimalPart}`;
}

